package com.optarena.app

fun formatUsd(cents: Int): String {
    val sign = if (cents < 0) "-" else ""
    val c = kotlin.math.abs(cents)
    return "$sign$${c / 100}.${(c % 100).toString().padStart(2, '0')}"
}

fun formatEur(cents: Int): String {
    val sign = if (cents < 0) "-" else ""
    val c = kotlin.math.abs(cents)
    return "$sign€${c / 100}.${(c % 100).toString().padStart(2, '0')}"
}

fun formatGbp(cents: Int): String {
    val sign = if (cents < 0) "-" else ""
    val c = kotlin.math.abs(cents)
    return "$sign£${c / 100}.${(c % 100).toString().padStart(2, '0')}"
}

