package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class MoneyFormatTest {

    @Test
    fun positiveAmounts() {
        assertEquals("$10.50", formatUsd(1050))
        assertEquals("€10.50", formatEur(1050))
        assertEquals("£10.50", formatGbp(1050))
    }

    @Test
    fun zeroAmount() {
        assertEquals("$0.00", formatUsd(0))
    }

    @Test
    fun negativeAmountsSignBeforeSymbol() {
        assertEquals("-$5.00", formatUsd(-500))
        assertEquals("-€5.00", formatEur(-500))
        assertEquals("-£5.00", formatGbp(-500))
    }
}

